import * as T from 'three';
import {CommonWeaponRenderer} from '../three/common-weapon-vfx.js';
import {loadCommonWeaponModels,commonModelAssets} from '../three/common-weapon-models.js';
import {COMMON_WEAPONS,commonWeaponStats} from '../fixed-parts/common-weapons.js';

// Supply art is an offscreen render of exactly the combat models/materials.
// Textures are generated by WebGL; no painted symbols or diagram fallback.
const caches=new WeakMap();

function fitThumbnailCamera(camera,fx,mechanic){
  const bounds=new T.Box3(),center=new T.Vector3(),size=new T.Vector3();
  // Frame the manufactured body, not a rocket's deliberately long wake.
  // Recompute per quality: visible upgrade parts and the mother drone differ.
  if(mechanic!=='gravity')for(const meshes of fx.models.batches.values())for(const mesh of meshes){
    if(!mesh.visible||!mesh.count)continue;
    mesh.computeBoundingBox();bounds.union(mesh.boundingBox);
  }
  for(const mesh of fx.droneSprites.meshes){
    if(!mesh.visible)continue;
    // The sprite batch publishes active-vertex bounds; its preallocated unused
    // vertices must not influence icon framing.
    if(mesh.geometry.boundingBox)bounds.union(mesh.geometry.boundingBox);
  }
  if(bounds.isEmpty())for(const batch of [fx.soft,fx.light]){
    const {placement,dimensions}=batch.geometry.attributes;
    for(let i=0;i<batch.count;i++){
      const x=placement.getX(i),y=placement.getY(i),a=placement.getZ(i);
      const c=Math.abs(Math.cos(a)),s=Math.abs(Math.sin(a)),w=dimensions.getX(i)/2,h=dimensions.getY(i)/2;
      const dx=c*w+s*h,dy=s*w+c*h;
      bounds.expandByPoint(new T.Vector3(x-dx,y-dy,0));bounds.expandByPoint(new T.Vector3(x+dx,y+dy,0));
    }
  }
  if(bounds.isEmpty()){bounds.min.set(-40,-40,0);bounds.max.set(40,40,0);}
  bounds.getCenter(center);bounds.getSize(size);
  const half=Math.max(24,Math.max(size.x,size.y)*.65);
  camera.left=-half;camera.right=half;camera.top=-half;camera.bottom=half;
  camera.position.set(center.x,center.y,200);camera.lookAt(center.x,center.y,0);camera.updateProjectionMatrix();
}

export function acquireCommonWeaponThumbnails(renderer,onReady=()=>{}){
  let cache=caches.get(renderer);
  if(!cache){
    // Offscreen targets do not inherit canvas AA. Share one multisample buffer;
    // cached icons need only the resolved color texture, not their own MSAA/depth.
    const antialiasedTarget=new T.WebGLRenderTarget(256,256,{depthBuffer:true,samples:2});
    const jobs=Object.values(COMMON_WEAPONS).flatMap(w=>Array.from({length:6},(_,rank)=>({w,rank,target:new T.WebGLRenderTarget(256,256,{depthBuffer:false})})));
    for(const j of jobs)j.target.texture.name='Common weapon / '+j.w.id+' / '+j.rank;
    cache={users:0,ready:false,textures:new Map(jobs.map(j=>[j.w.id+'/'+j.rank,j.target.texture])),callbacks:new Set()};
    const scene=new T.Scene(),root=new T.Group(),fx=new CommonWeaponRenderer(root);scene.add(root);
    scene.environment=renderer.scene.environment;scene.environmentIntensity=1.2;
    scene.add(new T.HemisphereLight(0xffffff,0x40566a,2));const lamp=new T.DirectionalLight(0xffffff,3);lamp.position.set(-40,-60,100);scene.add(lamp);
    const camera=new T.OrthographicCamera(-52,52,-52,52,.1,500);camera.position.set(0,0,200);camera.lookAt(0,0,0);
    let index=0;
    const render=three=>{
      if(cache.ready||!commonModelAssets.ready)return;
      const previous=three.getRenderTarget(),alpha=three.getClearAlpha(),color=three.getClearColor(new T.Color()),viewport=three.getViewport(new T.Vector4()),scissor=three.getScissor(new T.Vector4()),test=three.getScissorTest();
      try{
        three.setScissorTest(false);three.setClearColor(0,0);
        for(let count=0;count<6&&index<jobs.length;count++,index++){
          const {w,rank,target}=jobs[index],q=commonWeaponStats({itemId:w.id,qualityRank:rank}),k=w.mechanic;
          const v={...q,common:true,x:0,y:8,shape:k,unit:1.5,radius:25,alpha:1,age:1,progress:.35,angle:-.28,rank,highlight:q.highlight,durability:21,hp:rank>=2?2:1,bounces:rank>=3?4:0,generation:rank>=4?2:0};
          fx.begin(1);
          if(['laser','lightning','beam','freeze'].includes(k))fx.add({...v,shape:{laser:undefined,lightning:'lightning',beam:'cut-ray',freeze:'frost-ray'}[k],kind:'beam',points:[{x:-12,y:38},{x:12,y:-38}],x:-12,y:38,end:{x:12,y:-38},radius:k==='freeze'?12:7,width:k==='laser'?6:3});
          else if(k==='blades')fx.add({...v,shape:'slash',radius:32});
          else if(k==='gravity')fx.add({...v,y:30,radius:65});
          else if(k==='lightmine'){fx.add({...v,radius:15});for(let i=0;i<(rank===5?8:4);i++){const a=i*Math.PI*2/(rank===5?8:4);fx.segment('beam',v,v,{x:Math.sin(a)*44,y:8-Math.cos(a)*44},5,.7);}}
          else fx.add({...v,radius:k==='grenade'?18:k==='rocket'?9:k==='mine'?35:k==='toxin'?50:k==='drone'?rank===5?30:25:25,mother:k==='drone'&&rank===5,triggerRadius:40});
          fx.finish();fitThumbnailCamera(camera,fx,k);three.setRenderTarget(antialiasedTarget);three.clear();three.render(scene,camera);
          // Switching targets resolves MSAA before copying to the cached texture.
          three.setRenderTarget(target);three.copyTextureToTexture(antialiasedTarget.texture,target.texture);
        }
        if(index===jobs.length){cache.ready=true;for(const cb of cache.callbacks)queueMicrotask(cb);}
      }finally{three.setRenderTarget(previous);three.setViewport(viewport);three.setScissor(scissor);three.setScissorTest(test);three.setClearColor(color,alpha);}
    };
    cache.dispose=()=>{renderer.screenPasses.delete(render);fx.dispose();antialiasedTarget.dispose();jobs.forEach(j=>j.target.dispose());scene.clear();caches.delete(renderer);};
    renderer.screenPasses.add(render);caches.set(renderer,cache);
    loadCommonWeaponModels().catch(error=>console.warn('[common weapon models]',error));
  }
  cache.users++;cache.callbacks.add(onReady);if(cache.ready)queueMicrotask(onReady);let released=false;
  return {textures:cache.textures,get ready(){return cache.ready;},release(){if(released)return;released=true;cache.callbacks.delete(onReady);if(--cache.users===0)cache.dispose();}};
}
